        <div class="icon" aria-hidden="true">!</div>
        <button class="dialog-close" type="button" aria-label="Close dialog" data-close>&times;</button>
      </div>

      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
