      modal.classList.remove("is-open");
      trigger.setAttribute("aria-expanded", "false");
      trigger.focus();
    }

    trigger.setAttribute("aria-controls", "delete-modal");
    trigger.setAttribute("aria-expanded", "false");
    trigger.addEventListener("click", openDialog);

